import Foundation
import Security
// Tokens are scoped to this device and are never persisted in UserDefaults.
enum ServerVault {
 static let service="app.cryptoresearch.mobile.paper-server"
 static func save(_ value:String)throws{let query:[String:Any]=[kSecClass as String:kSecClassGenericPassword,kSecAttrService as String:service,kSecAttrAccount as String:"token"];let bytes=Data(value.utf8);let status=SecItemUpdate(query as CFDictionary,[kSecValueData as String:bytes] as CFDictionary);if status==errSecItemNotFound{var add=query;add[kSecValueData as String]=bytes;add[kSecAttrAccessible as String]=kSecAttrAccessibleWhenUnlockedThisDeviceOnly;guard SecItemAdd(add as CFDictionary,nil)==errSecSuccess else{throw StrategyError.invalid("보안 저장 실패")}}else if status != errSecSuccess{throw StrategyError.invalid("보안 저장 실패")}}
 static func read()->String{let q:[String:Any]=[kSecClass as String:kSecClassGenericPassword,kSecAttrService as String:service,kSecAttrAccount as String:"token",kSecReturnData as String:true,kSecMatchLimit as String:kSecMatchLimitOne];var item:CFTypeRef?;guard SecItemCopyMatching(q as CFDictionary,&item)==errSecSuccess,let d=item as? Data else{return ""};return String(data:d,encoding:.utf8) ?? ""}
 static func clear(){SecItemDelete([kSecClass as String:kSecClassGenericPassword,kSecAttrService as String:service] as CFDictionary)}
}
final class NoServerRedirects:NSObject,URLSessionTaskDelegate {
 func urlSession(_ session:URLSession,task:URLSessionTask,willPerformHTTPRedirection response:HTTPURLResponse,newRequest request:URLRequest,completionHandler:@escaping(URLRequest?)->Void){completionHandler(nil)}
}
enum PaperServerAPI {
 static func canonical(_ raw:String)throws->URL {guard let c=URLComponents(string:raw.trimmingCharacters(in:.whitespacesAndNewlines)),c.scheme?.lowercased()=="https",let host=c.host,!host.isEmpty,c.user==nil,c.password==nil,c.query==nil,c.fragment==nil,(c.path.isEmpty || c.path=="/"),let u=c.url else{throw StrategyError.invalid("HTTPS 서버 기본 주소만 입력하세요 (경로·계정·쿼리 제외)")};return u}
 static func request(base:String,token:String,path:String,body:[String:Any]?=nil)async throws->Data {let root=try canonical(base);guard token.count>=32,token.count<=512,!token.contains("\n"),!token.contains("\r"),["api/v1/status","api/v1/report","api/v1/sessions/start","api/v1/sessions/pause"].contains(path)else{throw StrategyError.invalid("서버 토큰/요청 확인 필요")};var request=URLRequest(url:root.appendingPathComponent(path));request.timeoutInterval=15;request.setValue("Bearer "+token,forHTTPHeaderField:"Authorization");request.setValue("application/json",forHTTPHeaderField:"Accept");if let body=body{request.httpMethod="POST";request.setValue("application/json",forHTTPHeaderField:"Content-Type");request.httpBody=try JSONSerialization.data(withJSONObject:body)};let config=URLSessionConfiguration.ephemeral;config.timeoutIntervalForResource=20;let delegate=NoServerRedirects();let session=URLSession(configuration:config,delegate:delegate,delegateQueue:nil);defer{session.invalidateAndCancel()};let(data,response)=try await session.data(for:request);guard data.count<=8*1024*1024,let http=response as? HTTPURLResponse else{throw StrategyError.invalid("서버 응답 형식 오류")};guard http.statusCode==200 else{if http.statusCode==401 || http.statusCode==403{throw StrategyError.invalid("서버 토큰/읽기·제어 권한을 확인하세요")};if http.statusCode==409{throw StrategyError.invalid("이미 실행 중입니다. 정지 후 새 세션을 시작하세요")};throw StrategyError.invalid("서버 응답 오류 (\(http.statusCode))")};return data}
}
